#!/usr/bin/env python3
"""Brainfuck interpreter.

Semantics / documentation
-------------------------
- Cells: 30000 unsigned bytes, initialized to 0, wrapping modulo 256
  (255 + 1 -> 0, 0 - 1 -> 255).
- Pointer movement is an ERROR, not clamped: moving the pointer below
  cell 0 or past cell 29999 raises BfError. (Chosen over clamping because
  silently clamping masks bugs in programs; a hard failure is easier to
  debug.)
- ',' reads one byte from the input stream; at end of input it stores 0
  (EOF-as-zero convention).
- Unmatched brackets are detected once, up front, and raise BfError with
  the offending source offset. Bracket matching is precomputed into a
  jump table before execution -- execution never rescans the program text
  to find matching brackets.
- All other characters are comments and ignored.

CLI: python bf.py file.bf   (reads stdin as program input)
"""

from __future__ import annotations

import sys

CELL_COUNT = 30000


class BfError(Exception):
    """Raised for invalid Brainfuck programs or runtime faults."""


def build_jump_table(program: str) -> dict[int, int]:
    """Precompute bracket matching. Returns {open_pos: close_pos, close_pos: open_pos}."""
    jump: dict[int, int] = {}
    stack: list[int] = []
    for i, ch in enumerate(program):
        if ch == "[":
            stack.append(i)
        elif ch == "]":
            if not stack:
                raise BfError(f"unmatched ']' at offset {i}")
            j = stack.pop()
            jump[j] = i
            jump[i] = j
    if stack:
        raise BfError(f"unmatched '[' at offset {stack[-1]}")
    return jump


def run(program: str, input_bytes: bytes = b"") -> bytes:
    """Execute Brainfuck `program`, return everything it wrote to stdout as bytes."""
    jump = build_jump_table(program)

    cells = bytearray(CELL_COUNT)
    ptr = 0
    out = bytearray()
    in_pos = 0
    ip = 0
    n = len(program)
    last_cell = CELL_COUNT - 1

    while ip < n:
        ch = program[ip]
        if ch == ">":
            if ptr == last_cell:
                raise BfError(f"pointer moved past cell {last_cell} at offset {ip}")
            ptr += 1
        elif ch == "<":
            if ptr == 0:
                raise BfError(f"pointer moved below cell 0 at offset {ip}")
            ptr -= 1
        elif ch == "+":
            cells[ptr] = (cells[ptr] + 1) & 0xFF
        elif ch == "-":
            cells[ptr] = (cells[ptr] - 1) & 0xFF
        elif ch == ".":
            out.append(cells[ptr])
        elif ch == ",":
            if in_pos < len(input_bytes):
                cells[ptr] = input_bytes[in_pos]
                in_pos += 1
            else:
                cells[ptr] = 0  # EOF
        elif ch == "[":
            if cells[ptr] == 0:
                ip = jump[ip]
        elif ch == "]":
            if cells[ptr] != 0:
                ip = jump[ip]
        # anything else: comment
        ip += 1

    return bytes(out)


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print(f"usage: {argv[0]} file.bf", file=sys.stderr)
        return 2
    try:
        with open(argv[1], encoding="utf-8") as f:
            program = f.read()
        output = run(program, sys.stdin.buffer.read())
    except OSError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    except BfError as e:
        print(f"brainfuck error: {e}", file=sys.stderr)
        return 1
    sys.stdout.buffer.write(output)
    sys.stdout.buffer.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

